using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "LockOnEffect", menuName = "Data/Battle/Effects/Sentinels/LockOnEffect")]
public class LockOnEffect : Effect
{
	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedOverCorruptChant() + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + GetLocalizedDescription();
	}
}
